import fs from 'node:fs';
import path from 'node:path';
const PERSON_ID='https://www.norbertbanhalmi.com/about/';
let entityChanged=0,htmlChanged=0,personObjects=0;
const entity=JSON.parse(fs.readFileSync('entity.jsonld','utf8'));const eg=Array.isArray(entity['@graph'])?entity['@graph']:[entity];const person=eg.find(n=>n?.['@id']===PERSON_ID&&(n?.['@type']==='Person'||(Array.isArray(n?.['@type'])&&n['@type'].includes('Person'))));if(!person)throw new Error('entity.jsonld canonical Person missing');if(Object.hasOwn(person,'homeLocation')){delete person.homeLocation;entityChanged=1;fs.writeFileSync('entity.jsonld',JSON.stringify(entity,null,2)+'\n');}
const skip=new Set(['.git','node_modules','_site','dist','coverage','assets','api','.well-known']);
function walk(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){if(e.isDirectory()&&skip.has(e.name))continue;const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(e.isFile()&&e.name.endsWith('.html'))migrate(p)}}
function migrate(file){let h=fs.readFileSync(file,'utf8'),changed=false;h=h.replace(/(<script\b[^>]*type=["']application\/ld\+json["'][^>]*>)([\s\S]*?)(<\/script>)/gi,(all,open,raw,close)=>{let data;try{data=JSON.parse(raw)}catch{return all}const graph=Array.isArray(data?.['@graph'])?data['@graph']:[data];let local=false;for(const n of graph){if(n?.['@id']===PERSON_ID&&(n?.['@type']==='Person'||(Array.isArray(n?.['@type'])&&n['@type'].includes('Person')))){personObjects++;if(Object.hasOwn(n,'homeLocation')){delete n.homeLocation;local=true;}}}if(local){changed=true;return open+JSON.stringify(data)+close}return all});if(changed){fs.writeFileSync(file,h);htmlChanged++;console.log(`${file}: removed Person.homeLocation business-location misuse`);}}
walk('.');if(personObjects<30)throw new Error(`embedded Person coverage unexpectedly low: ${personObjects}`);console.log(`Removed Person.homeLocation from canonical entity=${entityChanged}, HTML pages=${htmlChanged}; inspected ${personObjects} embedded Person objects.`);
